"""Offline interactive reports and the loopback dashboard, without CDNs."""
import csv
from hashlib import sha256
import json
from pathlib import Path
import secrets

from letf.lab.catalog import file_hash, private_bytes


def report_view(path):
    path=Path(path);report=json.loads(path.read_text());curves={}
    manifest=path.parent/'export-manifest.json'
    if manifest.exists():
        exported=json.loads(manifest.read_text())
        if exported['sha256'].get(path.name)!=file_hash(path):raise ValueError('Report export hash mismatch')
        for name,digest in exported['sha256'].items():
            p=path.parent/name
            if not p.resolve().is_relative_to(path.parent.resolve()) or p.is_symlink():raise ValueError('Unsafe export path')
            if file_hash(p)!=digest:raise ValueError('Export artifact checksum mismatch')
            if name.endswith('_curve.csv'):
                with p.open() as stream:
                    curves[name.removesuffix('_curve.csv')]=[
                        {'date':r['Unnamed: 0'] if 'Unnamed: 0'in r else r.get('date',next(iter(r.values()))),
                         'wealth':float(r['wealth']),'flow_neutral_wealth':float(r['flow_neutral_wealth'])}
                        for r in csv.DictReader(stream)]
    return {'report':report,'curves':curves,'report_sha256':file_hash(path)}


def _json_script(value):
    return json.dumps(value,allow_nan=False).replace('&','\\u0026').replace('<','\\u003c').replace('>','\\u003e').replace('\u2028','\\u2028').replace('\u2029','\\u2029')


def document(view=None, *, server_token=None):
    nonce=secrets.token_urlsafe(24)
    payload=_json_script({'view':view,'server_token':server_token})
    return TEMPLATE.replace('__NONCE__',nonce).replace('__PAYLOAD__',payload)


def render_report(report, output):
    view=report_view(report)
    private_bytes(output,document(view).encode())
    return {'output_sha256':file_hash(output),'report_sha256':view['report_sha256'],'external_requests':False}


